-- DRAFT: reviewable Blueprint program wording; do not apply before go-live approval.
-- Changes only sections 1.1, 5.1 and 6.1 of the template for future sends.
-- Existing sent/signed contracts and sections 3, 7 and 8 are untouched.
UPDATE contract_templates
   SET body = replace(replace(replace(body,
         '1.1 Capital Blueprint is a one-time educational assessment and written plan. Fundhub Education reviews the information you provide about your situation, and produces a written document that explains where you currently stand against common lender criteria, what the gaps appear to be, and the sequence of steps you may choose to work through to close them.',
         '1.1 Capital Blueprint is a twelve (12)-month educational planning and accountability program. Fundhub Education reviews the information you provide, prepares your written Blueprint, and provides a portal checklist that guides you through your plan. An AI accountability coach supports routine progress and follow-up. A separately assigned human advisor answers program questions and handles exceptions and funding preparation.'),
         '5.1 Tuition is {{field.package_fee}}, charged one time. There is no recurring billing and no subscription.',
         '5.1 Tuition is {{field.package_fee}}, charged one time, and includes twelve (12) months of program access beginning when Fundhub Education confirms your payment. There is no recurring billing and no subscription. No automatic renewal or charge after those twelve months is authorized by this Agreement. Any continued paid access requires a separately stated price and your agreement before billing.'),
         '6.1 The Blueprint is delivered digitally within fifteen (15) business days after Fundhub Education receives your completed intake and every item of information it requests from you. If you do not return requested information, that period is extended day for day. You may submit written clarification questions once within thirty (30) days after delivery, and Fundhub Education will respond in writing.',
         '6.1 Your initial written Blueprint is delivered digitally within fifteen (15) business days after Fundhub Education receives your completed intake and every item of information it requests from you. If you do not return requested information, that delivery period is extended day for day. During your included access period, your portal holds your plan, checklist and submitted proof. The AI accountability coach follows your current checklist step through text messages and automated voice calls, subject to your contact preferences. Your assigned human advisor handles program questions, exceptions and funding preparation. Your checklist and letters are updated when new credit information is received.'),
       updated_at = now()
 WHERE template_key = 'CAPITAL-BLUEPRINT-AGREEMENT';
